package com.fullinv;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("fullinv")
public interface FullInvConfig extends Config
{
    @ConfigItem(
        keyName = "enableHighlight",
        name = "Enable Highlight",
        description = "Toggle the red box highlight on/off",
        position = 1
    )
    default boolean enableHighlight()
    {
        return true;
    }

    @ConfigItem(
        keyName = "highlightDurationSec",
        name = "Highlight Duration (sec)",
        description = "How long the highlight lasts in seconds. Set to 0 for persistent highlight.",
        position = 2
    )
    default int highlightDurationSec()
    {
        return 3;
    }

    @ConfigItem(
        keyName = "showChatMessage",
        name = "Show Chat Message",
        description = "Toggle the chat notification on/off",
        position = 3
    )
    default boolean showChatMessage()
    {
        return true;
    }

    @ConfigItem(
        keyName = "includeUntradeables",
        name = "Include Untradeables",
        description = "Include 0 GP items in lowest value check",
        position = 4
    )
    default boolean includeUntradeables()
    {
        return true;
    }

    @ConfigItem(
        keyName = "ironmanMode",
        name = "Ironman Mode",
        description = "Use high alch value instead of GE value",
        position = 5
    )
    default boolean ironmanMode()
    {
        return false;
    }
}

package com.fullinv;

import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

public class FullInvOverlay extends Overlay
{
    private final Client client;
    private final FullInvPlugin plugin;

    @Inject
    FullInvOverlay(Client client, FullInvPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.shouldShowHighlight())
        {
            return null;
        }

        int slot = plugin.getHighlightSlot();
        if (slot < 0 || slot >= 28)
        {
            return null;
        }

        Widget inventoryWidget = client.getWidget(ComponentID.INVENTORY_CONTAINER);
        if (inventoryWidget == null || inventoryWidget.isHidden())
        {
            return null;
        }

        Widget[] children = inventoryWidget.getDynamicChildren();
        if (children == null || slot >= children.length)
        {
            return null;
        }

        Widget itemWidget = children[slot];
        if (itemWidget == null)
        {
            return null;
        }

        Rectangle bounds = itemWidget.getBounds();
        if (bounds == null)
        {
            return null;
        }

        graphics.setColor(new Color(255, 0, 0, 200));
        graphics.setStroke(new BasicStroke(2));
        graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);

        return null;
    }
}

package com.fullinv;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.text.NumberFormat;
import java.time.Instant;
import java.util.Locale;

@Slf4j
@PluginDescriptor(
    name = "Full Inv",
    description = "Highlights the lowest GE value item when inventory becomes full",
    tags = {"inventory", "full", "highlight", "value", "ge", "price"}
)
public class FullInvPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private FullInvConfig config;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private FullInvOverlay overlay;

    private boolean wasInventoryFull = false;

    @Getter
    private int highlightSlot = -1;

    @Getter
    private Instant highlightStartTime;

    @Override
    protected void startUp() throws Exception
    {
        overlayManager.add(overlay);
        wasInventoryFull = false;
        highlightSlot = -1;
        highlightStartTime = null;
        log.info("Full Inv plugin started");
    }

    @Override
    protected void shutDown() throws Exception
    {
        overlayManager.remove(overlay);
        wasInventoryFull = false;
        highlightSlot = -1;
        highlightStartTime = null;
        log.info("Full Inv plugin stopped");
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INVENTORY.getId())
        {
            return;
        }

        ItemContainer inventory = event.getItemContainer();
        if (inventory == null)
        {
            return;
        }

        Item[] items = inventory.getItems();
        int filledSlots = countFilledSlots(items);
        boolean isNowFull = filledSlots >= 28;

        if (!wasInventoryFull && isNowFull)
        {
            onInventoryBecameFull(items);
        }
        else if (wasInventoryFull && !isNowFull)
        {
            highlightSlot = -1;
            highlightStartTime = null;
        }

        wasInventoryFull = isNowFull;
    }

    private int countFilledSlots(Item[] items)
    {
        int count = 0;
        for (Item item : items)
        {
            if (item != null && item.getId() != -1)
            {
                count++;
            }
        }
        return count;
    }

    private void onInventoryBecameFull(Item[] items)
    {
        int lowestSlot = -1;
        long lowestValue = Long.MAX_VALUE;
        String lowestItemName = null;

        boolean useAlchValue = config.ironmanMode();

        for (int i = 0; i < items.length; i++)
        {
            Item item = items[i];
            if (item == null || item.getId() == -1)
            {
                continue;
            }

            int itemId = item.getId();
            int quantity = item.getQuantity();
            ItemComposition itemComp = itemManager.getItemComposition(itemId);
            int price = useAlchValue ? itemComp.getHaPrice() : itemManager.getItemPrice(itemId);

            if (!config.includeUntradeables() && price == 0)
            {
                continue;
            }

            long totalValue = (long) price * quantity;

            if (totalValue < lowestValue)
            {
                lowestValue = totalValue;
                lowestSlot = i;
                lowestItemName = itemComp.getName();
            }
        }

        if (lowestSlot == -1)
        {
            return;
        }

        highlightSlot = lowestSlot;
        highlightStartTime = Instant.now();
        log.info("Highlight set for slot {} item {}", lowestSlot, lowestItemName);

        if (config.showChatMessage() && lowestItemName != null)
        {
            sendChatMessage(lowestItemName, lowestValue, useAlchValue);
        }
    }

    private void sendChatMessage(String itemName, long value, boolean isAlchValue)
    {
        String formattedValue = NumberFormat.getNumberInstance(Locale.US).format(value);
        String valueLabel = isAlchValue ? "HA Value " : "GE Average ";

        final String chatMessage = new ChatMessageBuilder()
            .append(ChatColorType.HIGHLIGHT)
            .append("[Full Inv] ")
            .append(ChatColorType.NORMAL)
            .append("Lowest value: ")
            .append(ChatColorType.HIGHLIGHT)
            .append(itemName)
            .append(ChatColorType.NORMAL)
            .append(" (" + valueLabel + formattedValue + ")")
            .build();

        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(chatMessage)
            .build());
    }

    public boolean shouldShowHighlight()
    {
        if (!config.enableHighlight())
        {
            return false;
        }

        if (highlightSlot == -1 || highlightStartTime == null)
        {
            return false;
        }

        int durationSec = config.highlightDurationSec();
        if (durationSec == 0)
        {
            return true;
        }

        long elapsedMs = Instant.now().toEpochMilli() - highlightStartTime.toEpochMilli();
        long durationMs = durationSec * 1000L;
        if (elapsedMs > durationMs)
        {
            highlightSlot = -1;
            highlightStartTime = null;
            return false;
        }

        return true;
    }

    @Provides
    FullInvConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(FullInvConfig.class);
    }
}

package com.fullinv;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class FullInvPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(FullInvPlugin.class);
        RuneLite.main(args);
    }
}
